mapper.select:
SELECT l.*, t.name AS tenant_name, u.real_name AS real_name FROM ${log.database}.sys_login_log l LEFT JOIN ${log.database}.sys_tenant t ON t.id = l.tenant_id LEFT JOIN ${log.database}.sys_user u ON u.id = l.user_id WHERE 1=1
AND l.tenant_id = #{tenantId}
AND (l.username LIKE CONCAT('%', #{keyword}, '%') OR l.client_ip LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR t.name LIKE CONCAT('%', #{keyword}, '%'))
AND l.is_success = #{isSuccess}
AND l.login_time >= #{startTime}
AND l.login_time <= #{endTime}
ORDER BY
t.name u.real_name l.${sortField}
${sortOrder}
ORDER BY l.login_time DESC
